--
-- Name: acquire_staff_provisioning_authority_lock(uuid, uuid); Type: FUNCTION; Schema: access_control; Owner: -
--

CREATE FUNCTION access_control.acquire_staff_provisioning_authority_lock(requested_user_id uuid, requested_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF requested_user_id IS NULL OR requested_tenant_id IS NULL THEN
        RAISE check_violation USING MESSAGE = 'Provisioning authority scope is required';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(
        'orderhub.authorization.staff-provisioning:' || requested_tenant_id::TEXT || ':' || requested_user_id::TEXT, 0));
END;
$$;


--
-- Name: enforce_administrative_grant_permission_scope(); Type: FUNCTION; Schema: access_control; Owner: -
--

CREATE FUNCTION access_control.enforce_administrative_grant_permission_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    permission_scope TEXT;
BEGIN
    SELECT permission.administrative_scope
    INTO permission_scope
    FROM access_control.permissions permission
    WHERE permission.code = NEW.permission_code;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    IF permission_scope IS DISTINCT FROM NEW.scope_type THEN

        RAISE check_violation
            USING
                MESSAGE =
                    'Administrative grant permission and scope must be compatible',
                CONSTRAINT =
                    'ck_authorization_administrative_grant_permission_scope';
    END IF;

    RETURN NEW;
END;
$$;


