--
-- Name: reserve_role_code_namespace(); Type: FUNCTION; Schema: access_control; Owner: -
--

CREATE FUNCTION access_control.reserve_role_code_namespace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    requested_namespace TEXT;
    reserved_namespace TEXT;
BEGIN
    requested_namespace :=
        CASE
            WHEN NEW.mutability = 'TENANT_CUSTOM'
                THEN 'TENANT_CUSTOM'
            ELSE 'SYSTEM'
        END;

    INSERT INTO access_control.role_code_registry (
        code,
        role_namespace
    )
    VALUES (
        NEW.code,
        requested_namespace
    )
    ON CONFLICT (code)
    DO NOTHING
    RETURNING role_namespace
    INTO reserved_namespace;

    IF reserved_namespace IS NULL THEN
        SELECT registry.role_namespace
        INTO reserved_namespace
        FROM access_control.role_code_registry registry
        WHERE registry.code = NEW.code;
    END IF;

    IF reserved_namespace IS DISTINCT FROM requested_namespace THEN
        RAISE unique_violation
            USING
                MESSAGE =
                    'Role code is already reserved by another authorization namespace',
                CONSTRAINT =
                    'pk_authorization_role_code_registry';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: stabilize_staff_provisioning_authority(); Type: FUNCTION; Schema: access_control; Owner: -
--

CREATE FUNCTION access_control.stabilize_staff_provisioning_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    previous_scope TEXT;
    next_scope TEXT;
    locked_scope TEXT;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        previous_scope := OLD.tenant_id::TEXT || ':' || OLD.user_id::TEXT;
    END IF;
    IF TG_OP <> 'DELETE' THEN
        next_scope := NEW.tenant_id::TEXT || ':' || NEW.user_id::TEXT;
    END IF;
    FOR locked_scope IN
        SELECT scope FROM (VALUES (previous_scope), (next_scope)) scopes(scope)
        WHERE scope IS NOT NULL GROUP BY scope ORDER BY scope
    LOOP
        PERFORM pg_advisory_xact_lock(hashtextextended(
            'orderhub.authorization.staff-provisioning:' || locked_scope, 0));
    END LOOP;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;


