--
-- Name: acquire_governance_tenant_lock(uuid); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.acquire_governance_tenant_lock(requested_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF requested_tenant_id IS NULL THEN

        RAISE check_violation
            USING
                MESSAGE =
                    'Governance integrity requires a Tenant scope',
                CONSTRAINT =
                    'ck_workforce_governance_tenant_required';
    END IF;

    /*
     * All workforce mutations capable of removing a viable
     * TENANT_GOVERNANCE Staff relationship use this same
     * transaction-scoped lock.
     *
     * Hash collisions may over-serialize independent Tenants but
     * cannot weaken correctness.
     */
    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            'orderhub.workforce.governance:'
                || requested_tenant_id::TEXT,
            0
        )
    );

END;
$$;


--
-- Name: acquire_reporting_tenant_lock(uuid); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.acquire_reporting_tenant_lock(requested_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF requested_tenant_id IS NULL THEN

        RAISE check_violation
            USING
                MESSAGE =
                    'Reporting integrity requires a Tenant scope',
                CONSTRAINT =
                    'ck_workforce_reporting_tenant_required';
    END IF;

    /*
     * The advisory key is deliberately not persisted.
     *
     * A hash collision can only serialize two otherwise-independent Tenants;
     * it cannot weaken correctness.
     */
    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            'orderhub.workforce.reporting:'
                || requested_tenant_id::TEXT,
            0
        )
    );

END;
$$;


--
-- Name: enforce_inactive_staff_not_supervisor(); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.enforce_inactive_staff_not_supervisor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IS DISTINCT FROM NEW.status
        AND NEW.status = 'INACTIVE' THEN

        PERFORM workforce.acquire_reporting_tenant_lock(
            NEW.tenant_id
        );

        IF EXISTS (
            SELECT 1
            FROM workforce.reporting_relationships relationship
            WHERE relationship.tenant_id = NEW.tenant_id
              AND relationship.supervisor_staff_id =
                    NEW.staff_id
        ) THEN

            RAISE check_violation
                USING
                    MESSAGE =
                        'Staff with active subordinate relationships cannot become INACTIVE',
                    CONSTRAINT =
                        'ck_workforce_inactive_staff_not_supervisor';
        END IF;
    END IF;

    RETURN NEW;

END;
$$;


--
-- Name: enforce_placement_governance_integrity(); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.enforce_placement_governance_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    old_is_viable_governance BOOLEAN;
    new_is_viable_governance BOOLEAN;
    another_viable_governance_exists BOOLEAN;
BEGIN
    /*
     * DELETE and organizational-position changes may remove one
     * Staff relationship from the viable governance population.
     *
     * Acquire the Tenant lock before resolving position authority
     * so a concurrent position downgrade is visible afterwards.
     */
    PERFORM workforce.acquire_governance_tenant_lock(
        OLD.tenant_id
    );

    SELECT EXISTS (
        SELECT 1
        FROM workforce.staff_profiles staff
        JOIN workforce.job_positions position
          ON position.tenant_id =
                OLD.tenant_id
         AND position.position_id =
                OLD.position_id
        WHERE staff.tenant_id =
                OLD.tenant_id
          AND staff.staff_id =
                OLD.staff_id
          AND staff.status =
                'ACTIVE'
          AND position.authority_band =
                'TENANT_GOVERNANCE'
    )
    INTO old_is_viable_governance;

    IF NOT old_is_viable_governance THEN

        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;

        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN

        SELECT EXISTS (
            SELECT 1
            FROM workforce.staff_profiles staff
            JOIN workforce.job_positions position
              ON position.tenant_id =
                    NEW.tenant_id
             AND position.position_id =
                    NEW.position_id
            WHERE NEW.tenant_id =
                    OLD.tenant_id
              AND staff.tenant_id =
                    NEW.tenant_id
              AND staff.staff_id =
                    NEW.staff_id
              AND staff.status =
                    'ACTIVE'
              AND position.authority_band =
                    'TENANT_GOVERNANCE'
        )
        INTO new_is_viable_governance;

        IF new_is_viable_governance THEN
            RETURN NEW;
        END IF;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM workforce.staff_profiles staff
        JOIN workforce.staff_placements placement
          ON placement.tenant_id =
                staff.tenant_id
         AND placement.staff_id =
                staff.staff_id
        JOIN workforce.job_positions position
          ON position.tenant_id =
                placement.tenant_id
         AND position.position_id =
                placement.position_id
        WHERE staff.tenant_id =
                OLD.tenant_id
          AND staff.staff_id <>
                OLD.staff_id
          AND staff.status =
                'ACTIVE'
          AND position.authority_band =
                'TENANT_GOVERNANCE'
    )
    INTO another_viable_governance_exists;

    IF NOT another_viable_governance_exists THEN

        RAISE check_violation
            USING
                MESSAGE =
                    'Tenant must retain at least one ACTIVE Staff in TENANT_GOVERNANCE',
                CONSTRAINT =
                    'ck_workforce_last_governance_staff';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;

END;
$$;


--
-- Name: enforce_position_governance_integrity(); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.enforce_position_governance_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    affected_viable_governance_exists BOOLEAN;
    another_viable_governance_exists BOOLEAN;
BEGIN
    /*
     * Only a transition away from TENANT_GOVERNANCE can contract
     * the viable-governance population.
     */
    IF OLD.authority_band IS DISTINCT FROM 'TENANT_GOVERNANCE'
        OR NEW.authority_band = 'TENANT_GOVERNANCE' THEN

        RETURN NEW;
    END IF;

    PERFORM workforce.acquire_governance_tenant_lock(
        OLD.tenant_id
    );

    SELECT EXISTS (
        SELECT 1
        FROM workforce.staff_profiles staff
        JOIN workforce.staff_placements placement
          ON placement.tenant_id =
                staff.tenant_id
         AND placement.staff_id =
                staff.staff_id
        WHERE staff.tenant_id =
                OLD.tenant_id
          AND staff.status =
                'ACTIVE'
          AND placement.position_id =
                OLD.position_id
    )
    INTO affected_viable_governance_exists;

    IF NOT affected_viable_governance_exists THEN
        RETURN NEW;
    END IF;

    /*
     * OLD still has TENANT_GOVERNANCE inside this BEFORE trigger,
     * so exclude the entire position being downgraded.
     */
    SELECT EXISTS (
        SELECT 1
        FROM workforce.staff_profiles staff
        JOIN workforce.staff_placements placement
          ON placement.tenant_id =
                staff.tenant_id
         AND placement.staff_id =
                staff.staff_id
        JOIN workforce.job_positions position
          ON position.tenant_id =
                placement.tenant_id
         AND position.position_id =
                placement.position_id
        WHERE staff.tenant_id =
                OLD.tenant_id
          AND staff.status =
                'ACTIVE'
          AND position.authority_band =
                'TENANT_GOVERNANCE'
          AND position.position_id <>
                OLD.position_id
    )
    INTO another_viable_governance_exists;

    IF NOT another_viable_governance_exists THEN

        RAISE check_violation
            USING
                MESSAGE =
                    'Tenant must retain at least one ACTIVE Staff in TENANT_GOVERNANCE',
                CONSTRAINT =
                    'ck_workforce_last_governance_staff';
    END IF;

    RETURN NEW;

END;
$$;


--
-- Name: enforce_reporting_relationship_integrity(); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.enforce_reporting_relationship_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    supervisor_status TEXT;
    cycle_detected BOOLEAN;
BEGIN
    PERFORM workforce.acquire_reporting_tenant_lock(
        NEW.tenant_id
    );

    /*
     * This SELECT executes after acquisition of the Tenant transaction lock.
     * Under READ COMMITTED it therefore observes a competing transaction that
     * committed before this validation command begins.
     */
    SELECT staff.status
    INTO supervisor_status
    FROM workforce.staff_profiles staff
    WHERE staff.tenant_id = NEW.tenant_id
      AND staff.staff_id = NEW.supervisor_staff_id;

    IF supervisor_status IS DISTINCT FROM 'ACTIVE' THEN

        RAISE check_violation
            USING
                MESSAGE =
                    'Only ACTIVE Staff may remain an active supervisor',
                CONSTRAINT =
                    'ck_workforce_reporting_supervisor_active';
    END IF;

    /*
     * Adding supervisor -> subordinate creates a cycle exactly when an
     * existing path subordinate -> ... -> supervisor already exists.
     *
     * UPDATE excludes the edge being replaced from the recursive graph.
     */
    IF TG_OP = 'UPDATE' THEN

        WITH RECURSIVE reachable(staff_id) AS (

            SELECT relationship.subordinate_staff_id
            FROM workforce.reporting_relationships relationship
            WHERE relationship.tenant_id = NEW.tenant_id
              AND relationship.supervisor_staff_id =
                    NEW.subordinate_staff_id
              AND NOT (
                    relationship.tenant_id = OLD.tenant_id
                    AND relationship.supervisor_staff_id =
                        OLD.supervisor_staff_id
                    AND relationship.subordinate_staff_id =
                        OLD.subordinate_staff_id
              )

            UNION

            SELECT relationship.subordinate_staff_id
            FROM workforce.reporting_relationships relationship
            JOIN reachable
              ON relationship.supervisor_staff_id =
                    reachable.staff_id
            WHERE relationship.tenant_id = NEW.tenant_id
              AND NOT (
                    relationship.tenant_id = OLD.tenant_id
                    AND relationship.supervisor_staff_id =
                        OLD.supervisor_staff_id
                    AND relationship.subordinate_staff_id =
                        OLD.subordinate_staff_id
              )
        )
        SELECT EXISTS (
            SELECT 1
            FROM reachable
            WHERE reachable.staff_id =
                NEW.supervisor_staff_id
        )
        INTO cycle_detected;

    ELSE

        WITH RECURSIVE reachable(staff_id) AS (

            SELECT relationship.subordinate_staff_id
            FROM workforce.reporting_relationships relationship
            WHERE relationship.tenant_id = NEW.tenant_id
              AND relationship.supervisor_staff_id =
                    NEW.subordinate_staff_id

            UNION

            SELECT relationship.subordinate_staff_id
            FROM workforce.reporting_relationships relationship
            JOIN reachable
              ON relationship.supervisor_staff_id =
                    reachable.staff_id
            WHERE relationship.tenant_id = NEW.tenant_id
        )
        SELECT EXISTS (
            SELECT 1
            FROM reachable
            WHERE reachable.staff_id =
                NEW.supervisor_staff_id
        )
        INTO cycle_detected;

    END IF;

    IF cycle_detected THEN

        RAISE check_violation
            USING
                MESSAGE =
                    'Reporting relationship would create a Tenant workforce cycle',
                CONSTRAINT =
                    'ck_workforce_reporting_acyclic';
    END IF;

    RETURN NEW;

END;
$$;


--
-- Name: enforce_staff_governance_integrity(); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.enforce_staff_governance_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_is_viable_governance BOOLEAN;
    another_viable_governance_exists BOOLEAN;
BEGIN
    /*
     * The trigger is installed only for ACTIVE -> INACTIVE.
     * Serialize before reading current placement/position state.
     */
    PERFORM workforce.acquire_governance_tenant_lock(
        OLD.tenant_id
    );

    SELECT EXISTS (
        SELECT 1
        FROM workforce.staff_placements placement
        JOIN workforce.job_positions position
          ON position.tenant_id =
                placement.tenant_id
         AND position.position_id =
                placement.position_id
        WHERE placement.tenant_id =
                OLD.tenant_id
          AND placement.staff_id =
                OLD.staff_id
          AND position.authority_band =
                'TENANT_GOVERNANCE'
    )
    INTO target_is_viable_governance;

    IF NOT target_is_viable_governance THEN
        RETURN NEW;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM workforce.staff_profiles staff
        JOIN workforce.staff_placements placement
          ON placement.tenant_id =
                staff.tenant_id
         AND placement.staff_id =
                staff.staff_id
        JOIN workforce.job_positions position
          ON position.tenant_id =
                placement.tenant_id
         AND position.position_id =
                placement.position_id
        WHERE staff.tenant_id =
                OLD.tenant_id
          AND staff.staff_id <>
                OLD.staff_id
          AND staff.status =
                'ACTIVE'
          AND position.authority_band =
                'TENANT_GOVERNANCE'
    )
    INTO another_viable_governance_exists;

    IF NOT another_viable_governance_exists THEN

        RAISE check_violation
            USING
                MESSAGE =
                    'Tenant must retain at least one ACTIVE Staff in TENANT_GOVERNANCE',
                CONSTRAINT =
                    'ck_workforce_last_governance_staff';
    END IF;

    RETURN NEW;

END;
$$;


--
-- Name: enforce_staff_proof_consumption_deadline(); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.enforce_staff_proof_consumption_deadline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.consumed_at IS NULL AND NEW.consumed_at IS NOT NULL
       AND clock_timestamp() >= OLD.expires_at THEN
        RETURN NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_audit_event_mutation(); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.reject_audit_event_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE check_violation
        USING
            MESSAGE =
                'Workforce audit evidence is append-only',
            CONSTRAINT =
                'ck_workforce_audit_append_only';

    RETURN NULL;
END;
$$;


--
-- Name: reject_provisioning_event_mutation(); Type: FUNCTION; Schema: workforce; Owner: -
--

CREATE FUNCTION workforce.reject_provisioning_event_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE check_violation USING
        MESSAGE = 'Provisioning evidence is append-only',
        CONSTRAINT = 'ck_provisioning_event_append_only';
    RETURN NULL;
END;
$$;


