    CONSTRAINT ck_authorization_administrative_grant_audit_scope_shape CHECK ((((scope_type = 'PLATFORM'::text) AND (scope_id IS NULL)) OR ((scope_type = ANY (ARRAY['ORGANIZATION'::text, 'TENANT'::text])) AND (scope_id IS NOT NULL)))),
