--
-- Name: administrative_audit_events; Type: TABLE; Schema: catalog; Owner: -
--

CREATE TABLE catalog.administrative_audit_events (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    resource_id uuid NOT NULL,
    action text NOT NULL,
    before_revision bigint NOT NULL,
    after_revision bigint NOT NULL,
    correlation_id character varying(128) NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    currency_code text,
    before_minor_units bigint,
    after_minor_units bigint,
    CONSTRAINT ck_catalog_admin_action CHECK ((action = ANY (ARRAY['PRODUCT_CREATED'::text, 'PRODUCT_METADATA_CHANGED'::text, 'PRODUCT_ACTIVATED'::text, 'PRODUCT_ARCHIVED'::text, 'PRODUCT_CATEGORIES_CHANGED'::text, 'VARIANT_CREATED'::text, 'VARIANT_METADATA_CHANGED'::text, 'VARIANT_ACTIVATED'::text, 'VARIANT_DEACTIVATED'::text, 'VARIANT_ARCHIVED'::text, 'CATEGORY_CREATED'::text, 'CATEGORY_METADATA_CHANGED'::text, 'CATEGORY_REPARENTED'::text, 'BASE_PRICE_SET'::text]))),
    CONSTRAINT ck_catalog_admin_correlation CHECK (((correlation_id)::text ~ '^[A-Za-z0-9._:-]{1,128}$'::text)),
    CONSTRAINT ck_catalog_admin_price_evidence CHECK ((((action = 'BASE_PRICE_SET'::text) AND (currency_code IS NOT NULL) AND (currency_code ~ '^[A-Z]{3}$'::text) AND (after_minor_units IS NOT NULL) AND (after_minor_units >= 0) AND (((before_revision = 0) AND (before_minor_units IS NULL)) OR ((before_revision > 0) AND (before_minor_units IS NOT NULL) AND (before_minor_units >= 0)))) OR ((action <> 'BASE_PRICE_SET'::text) AND (currency_code IS NULL) AND (before_minor_units IS NULL) AND (after_minor_units IS NULL)))),
    CONSTRAINT ck_catalog_admin_revision CHECK (((before_revision >= 0) AND (before_revision < '9223372036854775807'::bigint) AND (after_revision = (before_revision + 1)) AND (((action = ANY (ARRAY['PRODUCT_CREATED'::text, 'VARIANT_CREATED'::text, 'CATEGORY_CREATED'::text])) AND (before_revision = 0)) OR (action = 'BASE_PRICE_SET'::text) OR ((action <> ALL (ARRAY['PRODUCT_CREATED'::text, 'VARIANT_CREATED'::text, 'CATEGORY_CREATED'::text])) AND (before_revision > 0)))))
);


