--
-- Name: product_variants; Type: TABLE; Schema: catalog; Owner: -
--

CREATE TABLE catalog.product_variants (
    tenant_id uuid NOT NULL,
    id uuid NOT NULL,
    product_id uuid NOT NULL,
    sku character varying(64) NOT NULL COLLATE pg_catalog."C",
    display_name text,
    gtin text,
    mpn text,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT ck_catalog_product_variants_display_name CHECK (((display_name IS NULL) OR (((char_length(display_name) >= 1) AND (char_length(display_name) <= 160)) AND (display_name = btrim(display_name, U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'::text)) AND (display_name !~ '[\u0000-\u001F\u007F-\u009F]'::text)))),
    CONSTRAINT ck_catalog_product_variants_gtin CHECK (((gtin IS NULL) OR ((char_length(gtin) = ANY (ARRAY[8, 12, 13, 14])) AND (gtin ~ '^[0-9]+$'::text) AND (((((((((((((((((ascii(substr(lpad(gtin, 14, '0'::text), 1, 1)) - 48) * 3) + (ascii(substr(lpad(gtin, 14, '0'::text), 2, 1)) - 48)) + ((ascii(substr(lpad(gtin, 14, '0'::text), 3, 1)) - 48) * 3)) + (ascii(substr(lpad(gtin, 14, '0'::text), 4, 1)) - 48)) + ((ascii(substr(lpad(gtin, 14, '0'::text), 5, 1)) - 48) * 3)) + (ascii(substr(lpad(gtin, 14, '0'::text), 6, 1)) - 48)) + ((ascii(substr(lpad(gtin, 14, '0'::text), 7, 1)) - 48) * 3)) + (ascii(substr(lpad(gtin, 14, '0'::text), 8, 1)) - 48)) + ((ascii(substr(lpad(gtin, 14, '0'::text), 9, 1)) - 48) * 3)) + (ascii(substr(lpad(gtin, 14, '0'::text), 10, 1)) - 48)) + ((ascii(substr(lpad(gtin, 14, '0'::text), 11, 1)) - 48) * 3)) + (ascii(substr(lpad(gtin, 14, '0'::text), 12, 1)) - 48)) + ((ascii(substr(lpad(gtin, 14, '0'::text), 13, 1)) - 48) * 3)) + (ascii(substr(lpad(gtin, 14, '0'::text), 14, 1)) - 48)) % 10) = 0)))),
    CONSTRAINT ck_catalog_product_variants_mpn CHECK (((mpn IS NULL) OR (((char_length(mpn) >= 1) AND (char_length(mpn) <= 70)) AND (mpn = btrim(mpn, U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'::text)) AND (mpn !~ '[\u0000-\u001F\u007F-\u009F]'::text)))),
    CONSTRAINT ck_catalog_product_variants_sku_control_characters CHECK (((sku)::text !~ '[\u0000-\u001F\u007F-\u009F]'::text)),
    CONSTRAINT ck_catalog_product_variants_sku_length CHECK (((char_length((sku)::text) >= 1) AND (char_length((sku)::text) <= 64))),
    CONSTRAINT ck_catalog_product_variants_sku_whitespace CHECK (((sku)::text = btrim((sku)::text, U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'::text))),
    CONSTRAINT ck_catalog_product_variants_status CHECK ((status = ANY (ARRAY['DRAFT'::text, 'ACTIVE'::text, 'INACTIVE'::text, 'ARCHIVED'::text]))),
    CONSTRAINT ck_catalog_variant_revision CHECK ((revision > 0))
);


