    CONSTRAINT ck_catalog_products_name CHECK (((char_length(name) > 0) AND (name = btrim(name, U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'::text)))),
    CONSTRAINT ck_catalog_products_slug CHECK ((((char_length((slug)::text) >= 2) AND (char_length((slug)::text) <= 256)) AND ((slug)::text ~ '^[A-Za-z0-9_-]+$'::text))),
    CONSTRAINT ck_catalog_products_status CHECK ((status = ANY (ARRAY['DRAFT'::text, 'ACTIVE'::text, 'ARCHIVED'::text])))
);


