    CONSTRAINT ck_inventory_commitments_backordered_non_negative CHECK ((backordered_quantity >= 0)),
    CONSTRAINT ck_inventory_commitments_reconciled CHECK (((allocated_quantity <= requested_quantity) AND (backordered_quantity <= requested_quantity) AND (allocated_quantity = (requested_quantity - backordered_quantity)))),
    CONSTRAINT ck_inventory_commitments_requested_positive CHECK ((requested_quantity > 0))
);


