    CONSTRAINT ck_inventory_positions_committed_not_above_on_hand CHECK ((committed <= on_hand)),
    CONSTRAINT ck_inventory_positions_on_hand_non_negative CHECK ((on_hand >= 0)),
    CONSTRAINT ck_inventory_positions_safety_stock_non_negative CHECK ((safety_stock >= 0))
);


