    occurred_at timestamp(6) with time zone NOT NULL,
    fingerprint_version integer NOT NULL,
    fingerprint text NOT NULL,
    CONSTRAINT ck_inventory_movement_delta CHECK (((delta <> 0) AND (delta >= '-9223372036854775807'::bigint) AND ((movement_type <> 'RECEIPT'::text) OR (delta > 0)))),
    CONSTRAINT ck_inventory_movement_fingerprint CHECK (((fingerprint_version = 1) AND (fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ck_inventory_movement_reason CHECK ((reason ~ '^[A-Z][A-Z0-9_]{0,63}$'::text)),
