    variant_id uuid,
    action text NOT NULL,
    before_safety_stock bigint,
    after_safety_stock bigint,
    before_policy text,
    after_policy text,
    reason text NOT NULL,
    correlation_id uuid NOT NULL,
    occurred_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ck_inventory_policy_change_reason CHECK ((reason ~ '^[A-Z][A-Z0-9_]{0,63}$'::text)),
    CONSTRAINT ck_inventory_policy_change_shape CHECK ((((action = 'SAFETY_STOCK'::text) AND (variant_id IS NOT NULL) AND (before_safety_stock IS NOT NULL) AND (before_safety_stock >= 0) AND (after_safety_stock IS NOT NULL) AND (after_safety_stock >= 0) AND (before_safety_stock <> after_safety_stock) AND (before_policy IS NULL) AND (after_policy IS NULL)) OR ((action = 'OVERSELL_POLICY'::text) AND (variant_id IS NULL) AND (before_safety_stock IS NULL) AND (after_safety_stock IS NULL) AND ((before_policy IS NULL) OR (before_policy = ANY (ARRAY['DENY'::text, 'ALLOW_BACKORDER'::text]))) AND (after_policy IS NOT NULL) AND (after_policy = ANY (ARRAY['DENY'::text, 'ALLOW_BACKORDER'::text])) AND (before_policy IS DISTINCT FROM after_policy))))
);


