    CONSTRAINT ck_order_request_idempotency_completion CHECK ((((state = 'PROCESSING'::text) AND (order_id IS NULL) AND (order_status IS NULL) AND (allocation_outcome IS NULL) AND (completed_at IS NULL)) OR ((state = 'COMPLETED'::text) AND (order_id IS NOT NULL) AND (order_status IS NOT NULL) AND (allocation_outcome IS NOT NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT ck_order_request_idempotency_key_digest_length CHECK ((octet_length(key_digest) = 32)),
    CONSTRAINT ck_order_request_idempotency_operation CHECK ((operation = 'CREATE_ORDER_V1'::text)),
    CONSTRAINT ck_order_request_idempotency_order_status CHECK (((order_status IS NULL) OR (order_status = 'CREATED'::text))),
    CONSTRAINT ck_order_request_idempotency_request_fingerprint_length CHECK ((octet_length(request_fingerprint) = 32)),
    CONSTRAINT ck_order_request_idempotency_state CHECK ((state = ANY (ARRAY['PROCESSING'::text, 'COMPLETED'::text])))
);


