    CONSTRAINT ck_organization_administrative_audit_action CHECK ((action_type = ANY (ARRAY['CREATE_ORGANIZATION'::text, 'SUSPEND_ORGANIZATION'::text, 'RECOVER_ORGANIZATION'::text, 'ATTACH_TENANT'::text, 'MOVE_TENANT'::text, 'DETACH_TENANT'::text]))),
    CONSTRAINT ck_organization_administrative_audit_after_status_vocabulary CHECK (((after_organization_status IS NULL) OR (after_organization_status = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text])))),
    CONSTRAINT ck_organization_administrative_audit_lifecycle_destination CHECK (((action_type <> ALL (ARRAY['SUSPEND_ORGANIZATION'::text, 'RECOVER_ORGANIZATION'::text])) OR ((action_type = 'SUSPEND_ORGANIZATION'::text) AND (after_organization_status = 'SUSPENDED'::text)) OR ((action_type = 'RECOVER_ORGANIZATION'::text) AND (after_organization_status = 'ACTIVE'::text)))),
    CONSTRAINT ck_organization_administrative_audit_outcome CHECK ((outcome = ANY (ARRAY['APPLIED'::text, 'NO_CHANGE'::text]))),
    CONSTRAINT ck_organization_administrative_audit_shape CHECK ((((action_type = 'CREATE_ORGANIZATION'::text) AND (tenant_id IS NULL) AND (before_organization_status IS NULL) AND (after_organization_status = 'ACTIVE'::text) AND (before_placement_organization_id IS NULL) AND (after_placement_organization_id IS NULL) AND (outcome = 'APPLIED'::text)) OR ((action_type = ANY (ARRAY['SUSPEND_ORGANIZATION'::text, 'RECOVER_ORGANIZATION'::text])) AND (tenant_id IS NULL) AND (before_organization_status IS NOT NULL) AND (after_organization_status IS NOT NULL) AND (before_placement_organization_id IS NULL) AND (after_placement_organization_id IS NULL) AND (((outcome = 'APPLIED'::text) AND (before_organization_status <> after_organization_status)) OR ((outcome = 'NO_CHANGE'::text) AND (before_organization_status = after_organization_status)))) OR ((action_type = 'ATTACH_TENANT'::text) AND (tenant_id IS NOT NULL) AND (before_organization_status IS NULL) AND (after_organization_status IS NULL) AND (((outcome = 'APPLIED'::text) AND (before_placement_organization_id IS NULL) AND (after_placement_organization_id = organization_id)) OR ((outcome = 'NO_CHANGE'::text) AND (before_placement_organization_id = organization_id) AND (after_placement_organization_id = organization_id)))) OR ((action_type = 'MOVE_TENANT'::text) AND (tenant_id IS NOT NULL) AND (outcome = 'APPLIED'::text) AND (before_organization_status IS NULL) AND (after_organization_status IS NULL) AND (before_placement_organization_id IS NOT NULL) AND (after_placement_organization_id = organization_id) AND (before_placement_organization_id <> after_placement_organization_id)) OR ((action_type = 'DETACH_TENANT'::text) AND (tenant_id IS NOT NULL) AND (before_organization_status IS NULL) AND (after_organization_status IS NULL) AND (after_placement_organization_id IS NULL) AND (((outcome = 'APPLIED'::text) AND (before_placement_organization_id = organization_id)) OR ((outcome = 'NO_CHANGE'::text) AND (before_placement_organization_id IS NULL)))))),
    CONSTRAINT ck_organization_administrative_audit_status_vocabulary CHECK (((before_organization_status IS NULL) OR (before_organization_status = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text]))))
);


