    CONSTRAINT ck_tenant_administrative_audit_status_vocabulary CHECK ((((before_status IS NULL) OR (before_status = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text]))) AND (after_status = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text]))))
