    CONSTRAINT ck_workforce_audit_action_type CHECK ((action_type = ANY (ARRAY['STAFF_ACTIVATED'::text, 'STAFF_DEACTIVATED'::text, 'DEPARTMENT_CHANGED'::text, 'POSITION_CHANGED'::text, 'POSITION_AUTHORITY_CHANGED'::text, 'SUPERVISOR_CHANGED'::text, 'PRIVILEGED_MUTATION'::text]))),
    CONSTRAINT ck_workforce_audit_after_authority_band CHECK (((after_authority_band IS NULL) OR (after_authority_band = ANY (ARRAY['OPERATIONAL'::text, 'SUPERVISORY'::text, 'COORDINATION'::text, 'MANAGEMENT'::text, 'TENANT_GOVERNANCE'::text])))),
    CONSTRAINT ck_workforce_audit_after_status CHECK (((after_status IS NULL) OR (after_status = ANY (ARRAY['ACTIVE'::text, 'INACTIVE'::text])))),
    CONSTRAINT ck_workforce_audit_before_authority_band CHECK (((before_authority_band IS NULL) OR (before_authority_band = ANY (ARRAY['OPERATIONAL'::text, 'SUPERVISORY'::text, 'COORDINATION'::text, 'MANAGEMENT'::text, 'TENANT_GOVERNANCE'::text])))),
    CONSTRAINT ck_workforce_audit_before_status CHECK (((before_status IS NULL) OR (before_status = ANY (ARRAY['ACTIVE'::text, 'INACTIVE'::text])))),
    CONSTRAINT ck_workforce_audit_outcome CHECK ((outcome = ANY (ARRAY['APPLIED'::text, 'DENIED'::text]))),
    CONSTRAINT ck_workforce_audit_reason_code CHECK (((reason_code IS NULL) OR (reason_code ~ '^[A-Z][A-Z0-9_]{2,63}$'::text)))
);


--
-- Name: departments; Type: TABLE; Schema: workforce; Owner: -
