    name text NOT NULL,
    CONSTRAINT ck_workforce_department_code CHECK ((btrim(code) <> ''::text)),
    CONSTRAINT ck_workforce_department_name CHECK ((btrim(name) <> ''::text))
);


--
-- Name: job_position_permissions; Type: TABLE; Schema: workforce; Owner: -
