);


--
-- Name: job_positions; Type: TABLE; Schema: workforce; Owner: -
--

CREATE TABLE workforce.job_positions (
    position_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    code text NOT NULL,
    title text NOT NULL,
    authority_band text NOT NULL,
    CONSTRAINT ck_workforce_position_authority_band CHECK ((authority_band = ANY (ARRAY['OPERATIONAL'::text, 'SUPERVISORY'::text, 'COORDINATION'::text, 'MANAGEMENT'::text, 'TENANT_GOVERNANCE'::text]))),
    CONSTRAINT ck_workforce_position_code CHECK ((btrim(code) <> ''::text)),
    CONSTRAINT ck_workforce_position_title CHECK ((btrim(title) <> ''::text))
);


--
-- Name: provisioning_events; Type: TABLE; Schema: workforce; Owner: -
--

CREATE TABLE workforce.provisioning_events (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    intent_id uuid NOT NULL,
    actor_user_id uuid NOT NULL,
    subject_user_id uuid,
    staff_id uuid,
    action text NOT NULL,
    correlation_id uuid NOT NULL,
    occurred_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_provisioning_event_action CHECK ((action = ANY (ARRAY['ISSUED'::text, 'COLD_START_ISSUED'::text, 'CONSUMED'::text, 'CANCELLED'::text]))),
    CONSTRAINT ck_provisioning_event_result CHECK ((((action = 'CONSUMED'::text) AND (subject_user_id IS NOT NULL) AND (staff_id IS NOT NULL)) OR ((action = ANY (ARRAY['ISSUED'::text, 'COLD_START_ISSUED'::text, 'CANCELLED'::text])) AND (subject_user_id IS NULL) AND (staff_id IS NULL))))
);


--
-- Name: reporting_relationships; Type: TABLE; Schema: workforce; Owner: -
