);


--
-- Name: staff_provisioning_intents; Type: TABLE; Schema: workforce; Owner: -
--

CREATE TABLE workforce.staff_provisioning_intents (
    intent_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    secret_digest bytea NOT NULL,
    issued_by_user_id uuid NOT NULL,
    department_id uuid NOT NULL,
    position_id uuid NOT NULL,
    initial_role_code text,
    operation_id uuid NOT NULL,
    request_fingerprint bytea NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    correlation_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_workforce_provisioning_intent_cancelled_after_creation CHECK (((cancelled_at IS NULL) OR (cancelled_at >= created_at))),
    CONSTRAINT ck_workforce_provisioning_intent_consumed_after_creation CHECK (((consumed_at IS NULL) OR (consumed_at >= created_at))),
    CONSTRAINT ck_workforce_provisioning_intent_consumed_before_expiry CHECK (((consumed_at IS NULL) OR (consumed_at < expires_at))),
    CONSTRAINT ck_workforce_provisioning_intent_expiry CHECK ((expires_at > created_at)),
    CONSTRAINT ck_workforce_provisioning_intent_fingerprint_length CHECK ((octet_length(request_fingerprint) = 32)),
    CONSTRAINT ck_workforce_provisioning_intent_role_code CHECK (((initial_role_code IS NULL) OR (initial_role_code ~ '^[A-Z][A-Z0-9_]{2,63}$'::text))),
    CONSTRAINT ck_workforce_provisioning_intent_secret_digest_length CHECK ((octet_length(secret_digest) = 32)),
    CONSTRAINT ck_workforce_provisioning_intent_terminal_exclusive CHECK ((NOT ((consumed_at IS NOT NULL) AND (cancelled_at IS NOT NULL))))
);


